-- Ejecutar en Supabase → SQL Editor → New query → Run.
-- Requiere umamusume.sql y umamusume_global_cards.sql.
--
-- Tiers de la version global (uma.moe), una lista por stat.
-- Emparejado por el id oficial de la carta, que viene dentro de la URL del
-- icono (Support_Card_<id>_Card.png): la correspondencia es exacta.
--
-- Se puede repetir: limpia los tiers de global antes de escribirlos.

alter table public.umamusume_support_cards add column if not exists tier text;

update public.umamusume_support_cards set tier = null where version = 'global';

update public.umamusume_support_cards set tier = 'S+' where version = 'global' and id = 'SSR_Ines_Fujin_(Watch_My_Star_Fly!)';
